con:restMockService.con:startScript:
// SoapUI's embedded Jetty 6 keeps the 4 KB default header buffer, so a browser with a few
// cookies on localhost gets HTTP 413. Jetty is started after this script returns, so raise
// the buffer from a background thread once the connector exists. New connections pick it up.
Thread.start {
    def engine = com.eviware.soapui.SoapUI.getMockEngine()
    def f = engine.class.getDeclaredField("connectors"); f.accessible = true
    for (int i = 0; i < 150; i++) {
        def map = f.get(engine)
        if (map && !map.isEmpty()) {
            // The public setters throw IllegalStateException once Jetty is started, so poke the fields.
            def cls = org.mortbay.jetty.AbstractBuffers
            ["_headerBufferSize", "_requestBufferSize"].each { name ->
                def bf = cls.getDeclaredField(name); bf.accessible = true
                map.values().each { c -> bf.setInt(c, 65536) }
            }
            log.info("mock gateway: jetty header buffer raised to 64 KB")
            return
        }
        Thread.sleep(200)
    }
    log.warn("mock gateway: could not find jetty connector to raise header buffer")
}

con:restMockAction.con:dispatchPath:
import java.math.RoundingMode import java.util.concurrent.ConcurrentHashMap import groovy.json.JsonOutput import groovy.json.JsonSlurper
// Bill store: one map per JVM, shared by every action (each action's script has its own classloader). def bills = System.properties.computeIfAbsent("pizza.bills") { new ConcurrentHashMap() }
def req = new JsonSlurper().parseText(mockRequest.requestContent) def orderId = req.orderId.toString().toLowerCase() def id = "bill_" + orderId.take(8) + "_" + System.currentTimeMillis() bills[id] = [ orderId : orderId, amount : new BigDecimal(req.amount.toString()).setScale(2, RoundingMode.HALF_UP).toPlainString(), redirectUrl: req.redirectUrl, callbackUrl: req.callbackUrl] log.info("created " + id + " for order " + orderId + " amount " + bills[id].amount) requestContext.body = JsonOutput.toJson([id: id, url: "http://localhost:8090/pay/" + id]) return "Created"

import java.net.http.HttpClient
import java.net.http.HttpRequest
import java.net.http.HttpResponse
import java.time.Duration
import java.time.Instant
import java.time.temporal.ChronoUnit
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

def bills = System.properties.computeIfAbsent("pizza.bills") { new ConcurrentHashMap() }
def id = mockRequest.path.tokenize("/").last()
def bill = bills[id]
if (!bill) return "Unknown bill"

def form = (mockRequest.requestContent ?: "").tokenize("&").collectEntries {
    def kv = it.split("=", 2)
    [(URLDecoder.decode(kv[0], "UTF-8")): kv.length > 1 ? URLDecoder.decode(kv[1], "UTF-8") : ""]
}
def fields = [
    amount  : bill.amount,
    id      : id,
    order_id: bill.orderId,
    paid    : (form.action == "pay").toString(),
    paid_at : Instant.now().truncatedTo(ChronoUnit.SECONDS).toString()]

// Must match the API's SignatureService byte for byte: sorted keys, key=value, joined by "|".
def signed = ["amount", "id", "order_id", "paid", "paid_at"].collect { it + "=" + fields[it] }.join("|")
def key = System.getenv("GATEWAY_SIGNATURE_KEY") ?: "mock-signature-key"
def mac = Mac.getInstance("HmacSHA256")
mac.init(new SecretKeySpec(key.getBytes("UTF-8"), "HmacSHA256"))
fields.x_signature = mac.doFinal(signed.getBytes("UTF-8")).encodeHex().toString()

def body = fields.collect { k, v -> URLEncoder.encode(k, "UTF-8") + "=" + URLEncoder.encode(v, "UTF-8") }.join("&")
def url = System.getenv("API_CALLBACK_URL") ?: bill.callbackUrl
try {
    def resp = HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).connectTimeout(Duration.ofSeconds(5)).build()
        .send(HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10))
            .header("Content-Type", "application/x-www-form-urlencoded")
            .POST(HttpRequest.BodyPublishers.ofString(body)).build(),
            HttpResponse.BodyHandlers.ofString())
    if (resp.statusCode() == 200) log.info("callback " + id + " paid=" + fields.paid + " -> 200")
    else log.warn("callback " + id + " -> " + resp.statusCode() + " " + resp.body())
} catch (Exception ex) {
    log.warn("callback " + id + " to " + url + " failed: " + ex)
}
requestContext.location = bill.redirectUrl
return "Redirect"
